function makeScene(world: World): void {
    const ambient = world.resource(GlobalAmbientLight);
    ambient.color = 0xd8e4ff;
    ambient.brightness = 380;

    const sun = world.create();
    world.add(sun, Transform, { rotation: lookAtRotation(0, 0, 0, 1, -2, -0.35) });
    world.add(sun, DirectionalLight, { color: 0xffe8cc, illuminance: 6000, shadowMapsEnabled: 1 });

    const camera = world.create();
    world.add(camera, Camera, { clearColor: 0x191816 });
    world.add(camera, StandardRenderer);
    world.add(camera, Orbit, { distance: 12, yaw: 0.7, pitch: 0.35 });
    world.add(camera, Transform);
    world.storage(Orbit).pan.set(camera, 0, 1.5, 0);

    // Unit box hull (half-extent 0.5); each body sizes it through its Transform scale,
    // matching the built-in unit cube mesh so the visuals line up with the collider.
    const unitBox = world.resource(Hulls).add({ name: "box", halfExtents: [0.5, 0.5, 0.5] });
    const materials = world.resource(Materials);

    const floorMaterial = materials.add(
        StandardMaterial({ baseColor: [0.5, 0.5, 0.5, 1], perceptualRoughness: 0.9 }),
    );
    const floor = world.create();
    world.add(floor, Transform, { translation: [0, FLOOR_TOP - 0.5, 0], scale: [12, 1, 12] });
    world.add(floor, Body); // static by default
    world.add(floor, Shape, { geometry: unitBox });
    world.add(floor, MeshInstance);
    world.add(floor, MeshMaterial, floorMaterial);
    world.add(floor, Floor);

    const boxMaterial = materials.add(
        StandardMaterial({ baseColor: [0.05, 0.25, 0.95, 1], perceptualRoughness: 0.5 }),
    );
    const box = world.create();
    // A slight tilt so it tips onto a face when it lands.
    const tilt = 0.12;
    world.add(box, Transform, {
        translation: [0, DROP_HEIGHT, 0],
        rotation: [Math.sin(tilt), 0, Math.sin(tilt * 0.5), Math.cos(tilt)].map(
            (v, _, q) => v / Math.hypot(...q),
        ) as [number, number, number, number],
    });
    world.add(box, Body, { type: BodyType.Dynamic });
    world.add(box, Shape, { geometry: unitBox });
    world.add(box, MeshInstance);
    world.add(box, MeshMaterial, boxMaterial);
    world.add(box, FallingBox);
